-- Hand-written Reading and Writing questions for timed modules, at SAT difficulty.
-- Generated by scripts/question-bank/build.py. No API calls are needed to use them.

insert into public.questions (skill_id, difficulty, passage, stem, choices, answer, explanation, model) values
  ('words_in_context', 'easy', 'The new bus route has been ______ for commuters on the east side of town. Trips that once took an hour now take twenty minutes, and riders no longer have to change buses.', 'Which choice completes the text with the most logical and precise word or phrase?', '["unnoticed", "expensive", "helpful", "confusing"]'::jsonb, 'C', 'Shorter trips and no transfers are benefits, so “helpful” fits. The other choices describe problems or a lack of impact that the text doesn’t support.', 'hand-written'),
  ('words_in_context', 'easy', 'Sea otters are known for their ______ fur. With up to a million hairs per square inch, it is the densest coat of any mammal and keeps them warm in icy water.', 'Which choice completes the text with the most logical and precise word or phrase?', '["thick", "bright", "loose", "rough"]'::jsonb, 'A', '“Densest coat” with a million hairs per square inch means the fur is thick. Nothing in the text mentions color, looseness, or texture.', 'hand-written'),
  ('words_in_context', 'easy', 'Maya Lin was only twenty-one when her design for the Vietnam Veterans Memorial was chosen. Although she was still a student, the judges ______ her plan over more than a thousand other entries.', 'Which choice completes the text with the most logical and precise word or phrase?', '["selected", "questioned", "copied", "ignored"]'::jsonb, 'A', 'Her design “was chosen,” so the judges selected it. “Ignored” and “questioned” contradict that, and nothing suggests copying.', 'hand-written'),
  ('words_in_context', 'easy', 'The bakery’s owner decided to ______ her hours during the holidays. Instead of closing at five, the shop now stays open until nine to serve extra customers.', 'Which choice completes the text with the most logical and precise word or phrase?', '["extend", "shorten", "forget", "announce"]'::jsonb, 'A', 'Moving closing time from five to nine lengthens the hours. “Announce” is possible in general, but the example shows the hours themselves growing.', 'hand-written'),
  ('words_in_context', 'easy', 'Because the desert receives so little rain, its plants must be ______ with water. Many cacti store moisture in their stems and release it slowly over months.', 'Which choice completes the text with the most logical and precise word or phrase?', '["generous", "bored", "careful", "wasteful"]'::jsonb, 'C', 'Storing water and releasing it slowly shows plants being careful with a scarce resource. “Wasteful” and “generous” say the opposite.', 'hand-written'),
  ('words_in_context', 'easy', 'The two brothers had very ______ interests. One spent every weekend hiking in the mountains, while the other rarely left his apartment and preferred to paint.', 'Which choice completes the text with the most logical and precise word or phrase?', '["popular", "different", "similar", "secret"]'::jsonb, 'B', 'The sentence contrasts hiking outdoors with painting indoors, so their interests are different. “Similar” reverses that contrast.', 'hand-written'),
  ('words_in_context', 'medium', 'Early reviewers dismissed Zora Neale Hurston’s novel for its use of Southern Black dialect, but later scholars have ______ that same feature, arguing that her ear for spoken language is what gives the book its lasting power.', 'Which choice completes the text with the most logical and precise word or phrase?', '["overlooked", "imitated", "praised", "disputed"]'::jsonb, 'C', 'The word “but” sets later scholars against the early dismissal, and they say the feature gives the book its power, so they praised it. “Disputed” would agree with the critics, and “overlooked” conflicts with discussing it.', 'hand-written'),
  ('words_in_context', 'medium', 'Engineers often describe concrete as a surprisingly ______ material. Although it resists enormous crushing forces, it cracks easily when stretched, which is why builders embed steel bars inside it to carry tension.', 'Which choice completes the text with the most logical and precise word or phrase?', '["lightweight", "uneven", "temporary", "flexible"]'::jsonb, 'B', 'Concrete is strong in one way and weak in another, so its performance is uneven. It cracks when stretched, which rules out “flexible,” and the text says nothing about weight or lifespan.', 'hand-written'),
  ('words_in_context', 'medium', 'The historian’s account of the 1918 influenza outbreak is notably ______: rather than relying on government records alone, she draws on diaries, hospital ledgers, and letters from dozens of small towns.', 'Which choice completes the text with the most logical and precise word or phrase?', '["brief", "thorough", "biased", "outdated"]'::jsonb, 'B', 'The colon introduces a list of many kinds of sources, which shows thoroughness. Nothing suggests the account is short, slanted, or old.', 'hand-written'),
  ('words_in_context', 'medium', 'Honeybees that find a rich patch of flowers do not keep the discovery to themselves. Returning to the hive, a forager performs a “waggle dance” that ______ the distance and direction of the food to her nestmates.', 'Which choice completes the text with the most logical and precise word or phrase?', '["conceals", "conveys", "exaggerates", "restricts"]'::jsonb, 'B', 'The first sentence says bees share what they find, so the dance communicates, or conveys, the location. “Conceals” is the opposite, and nothing suggests the information is inflated.', 'hand-written'),
  ('words_in_context', 'medium', 'Critics of the proposed dam argue that its benefits have been ______. They note that the projected electricity output relies on rainfall figures from an unusually wet decade and is unlikely to be reached in a typical year.', 'Which choice completes the text with the most logical and precise word or phrase?', '["undisclosed", "overstated", "postponed", "misplaced"]'::jsonb, 'B', 'Output projections based on an unusually wet decade make the benefits look larger than they are: overstated. The benefits are publicly projected, so “undisclosed” doesn’t fit.', 'hand-written'),
  ('words_in_context', 'medium', 'Though the composer’s late symphonies are now staples of the concert hall, audiences at their premieres were ______. Contemporary newspapers describe half-empty seats and polite, scattered applause rather than outrage or enthusiasm.', 'Which choice completes the text with the most logical and precise word or phrase?', '["indifferent", "mistaken", "hostile", "delighted"]'::jsonb, 'A', 'Half-empty seats and polite applause, “rather than outrage or enthusiasm,” describe indifference. “Hostile” and “delighted” are the two reactions the text specifically rules out.', 'hand-written'),
  ('words_in_context', 'hard', 'The biologist Lynn Margulis spent years defending the idea that complex cells arose when simpler organisms merged. Her colleagues initially treated the theory as eccentric, yet genetic evidence eventually proved so ______ that the claim, once a fringe position, now appears in standard textbooks.', 'Which choice completes the text with the most logical and precise word or phrase?', '["conventional", "compelling", "ambiguous", "fragmentary"]'::jsonb, 'B', 'Evidence that moved a fringe idea into textbooks must have been convincing, or compelling. “Ambiguous” and “fragmentary” would not have won over skeptics, and “conventional” describes the theory’s later status, not the evidence.', 'hand-written'),
  ('words_in_context', 'hard', 'In her study of nineteenth-century factory towns, the economist does not claim that wages alone explain workers’ migration; she is careful to ______ her argument, noting that family ties, housing, and religious communities also shaped where people chose to settle.', 'Which choice completes the text with the most logical and precise word or phrase?', '["abandon", "qualify", "reiterate", "popularize"]'::jsonb, 'B', 'To qualify an argument is to limit it by adding conditions, which is what noting other factors does. She doesn’t give it up (“abandon”), and adding other factors is more than repeating it (“reiterate”).', 'hand-written'),
  ('words_in_context', 'hard', 'Some philosophers of science warn against treating a successful theory as a final truth. History, they observe, is littered with models that predicted observations accurately for generations before being replaced. On this view, a theory’s present success is ______ evidence of its truth: encouraging, perhaps, but far from conclusive.', 'Which choice completes the text with the most logical and precise word or phrase?', '["irrelevant", "irrefutable", "provisional", "deceptive"]'::jsonb, 'C', '“Encouraging, perhaps, but far from conclusive” means the evidence holds for now and could be revised: provisional. “Irrefutable” contradicts “far from conclusive,” and “irrelevant” and “deceptive” are too dismissive of “encouraging.”', 'hand-written'),
  ('words_in_context', 'hard', 'Readers who come to Marianne Moore’s poems expecting grand emotional declarations may find them ______. Moore preferred precise observation to open confession, and her feeling tends to surface obliquely, through a carefully chosen detail about an animal or an object rather than a direct statement.', 'Which choice completes the text with the most logical and precise word or phrase?', '["chaotic", "reticent", "sentimental", "derivative"]'::jsonb, 'B', 'Poems that avoid open confession and let feeling surface only indirectly are reserved, or reticent. “Sentimental” is the opposite, and nothing suggests disorder or imitation.', 'hand-written'),
  ('words_in_context', 'hard', 'The treaty’s drafters deliberately left several key terms undefined. Far from an oversight, this ______ allowed delegations with sharply opposed positions to sign the same document, each confident that it could later interpret the language in its own favor.', 'Which choice completes the text with the most logical and precise word or phrase?', '["rigidity", "secrecy", "vagueness", "urgency"]'::jsonb, 'C', 'Undefined terms that each side can read its own way are examples of vagueness. “Rigidity” is the opposite, and nothing in the text concerns speed or keeping the terms hidden.', 'hand-written'),
  ('words_in_context', 'hard', 'Archaeologists had long assumed that the settlement was abandoned suddenly after a catastrophe. New excavations ______ that assumption: layers of carefully sealed storerooms and the orderly removal of tools suggest residents departed gradually and may have expected to return.', 'Which choice completes the text with the most logical and precise word or phrase?', '["exemplify", "corroborate", "undermine", "anticipate"]'::jsonb, 'C', 'A gradual, planned departure conflicts with a sudden abandonment, so the evidence undermines the assumption. “Corroborate” and “exemplify” would mean the evidence supports it.', 'hand-written'),
  ('text_structure', 'easy', 'Many people think bats are blind, but this is a myth. All bat species can see, and some larger fruit bats have excellent vision. Many bats also use echolocation, but they use it in addition to their eyesight, not in place of it.', 'Which choice best states the main purpose of the text?', '["To argue that bats should be protected", "To compare fruit bats with other mammals", "To correct a common mistaken belief about bats", "To explain how echolocation was discovered"]'::jsonb, 'C', 'The text opens by calling the belief a myth and then gives the facts. It never covers discovery, other mammals, or protection.', 'hand-written'),
  ('text_structure', 'easy', 'The town of Greenfield used to send all of its food scraps to a landfill. In 2019, the council started a compost program. Within two years, the amount of trash leaving the town had fallen by a third.', 'Which choice best describes the overall structure of the text?', '["It presents an argument and then rejects it.", "It compares two towns’ approaches to trash.", "It describes a problem, a response to it, and the result.", "It lists the steps for making compost at home."]'::jsonb, 'C', 'Landfill waste is the problem, composting is the response, and less trash is the result. Only one town appears, and no instructions are given.', 'hand-written'),
  ('text_structure', 'easy', 'To make a paper airplane fly farther, start with a sharp center fold. Keep the nose heavy by folding it several times, and make sure both wings are the same size. Finally, throw it gently rather than hard.', 'Which choice best states the main purpose of the text?', '["To explain the history of paper airplanes", "To give advice on improving a paper airplane’s flight", "To persuade readers to take up a new hobby", "To describe how real airplanes are built"]'::jsonb, 'B', 'Each sentence gives a practical tip for flying farther. There’s no history, argument for a hobby, or discussion of real aircraft.', 'hand-written'),
  ('text_structure', 'easy', 'Octopuses are remarkable escape artists. In one aquarium, an octopus squeezed through a small drain and made its way to the sea. Because they have no bones, they can fit through almost any opening larger than their beak.', 'Which choice best describes the function of the second sentence in the text as a whole?', '["It explains why octopuses have no bones.", "It challenges the claim in the first sentence.", "It gives a specific example of the claim in the first sentence.", "It introduces a new topic unrelated to escaping."]'::jsonb, 'C', 'The drain story illustrates “escape artists.” It supports the first sentence, and the bones explanation comes only in the third sentence.', 'hand-written'),
  ('text_structure', 'medium', 'For decades, researchers assumed that the sounds of a coral reef were mere background noise. Marine ecologist Steve Simpson tested this idea by playing recordings of healthy reefs through underwater speakers on damaged reefs. Young fish arrived in far greater numbers at the sites with speakers than at silent sites, suggesting that fish use sound to find places to settle.', 'Which choice best states the main purpose of the text?', '["To present a study showing that reef sounds influence where young fish settle", "To describe why researchers no longer study coral reefs", "To argue that damaged reefs can be restored only with speakers", "To explain how fish produce sounds on a healthy reef"]'::jsonb, 'A', 'The text sets up an assumption and reports an experiment that challenges it. It never claims speakers are the only way to restore reefs, and it doesn’t explain how fish make sounds.', 'hand-written'),
  ('text_structure', 'medium', 'The printing press is usually credited with spreading literacy across Europe. Yet historians point out that books remained too expensive for most people for more than a century after its invention. What changed reading habits more directly, they argue, was the later growth of cheap pamphlets and newspapers, which put printed words within ordinary budgets.', 'Which choice best describes the overall structure of the text?', '["It states a common view, raises a difficulty with it, and offers a different explanation.", "It defends a traditional view against a recent criticism.", "It traces the invention of the printing press step by step.", "It compares the prices of books in several European countries."]'::jsonb, 'A', '“Usually credited” is the common view, “Yet” raises the problem, and pamphlets are the alternative. The text challenges the traditional view rather than defending it.', 'hand-written'),
  ('text_structure', 'medium', 'The painter Jacob Lawrence told the story of the Great Migration in sixty small panels. Each panel uses only a few flat colors and simple shapes. This restraint might seem to limit what he could express, but it gives the series a steady rhythm, so that viewers feel the movement of a whole people rather than the drama of one individual.', 'Which choice best describes the function of the third sentence in the text as a whole?', '["It summarizes the historical causes of the Great Migration.", "It shifts the discussion from Lawrence to other painters of his time.", "It offers evidence that Lawrence’s panels were poorly received.", "It anticipates a possible objection to Lawrence’s style before explaining the style’s effect."]'::jsonb, 'D', '“Might seem to limit” raises a doubt, and “but” turns to the benefit. No reception, other painters, or historical causes are mentioned.', 'hand-written'),
  ('text_structure', 'medium', 'Most people picture glaciers as slow and silent, but they can be surprisingly noisy. As ice shifts over bedrock, it cracks and groans. Near the ocean, trapped air bubbles burst as the ice melts, releasing a constant fizz. Scientists now use underwater microphones to measure these sounds and estimate how quickly a glacier is losing ice.', 'Which choice best states the main purpose of the text?', '["To warn that glaciers are dangerous to approach", "To explain how air becomes trapped in glacial ice", "To argue that microphones are better than satellites for studying ice", "To show that glacier sounds are both unexpected and scientifically useful"]'::jsonb, 'D', 'The text moves from a surprising fact to its use in measurement. Satellites are never mentioned, and how air gets trapped isn’t explained.', 'hand-written'),
  ('text_structure', 'hard', 'Economists once treated the decision to save money as a straightforward calculation of future needs. Behavioral researchers complicated that picture by showing that people often behave inconsistently, resolving to save yet spending anyway. Rather than concluding that savers are simply irrational, however, Richard Thaler proposed changing the setting in which choices are made: when employees were automatically enrolled in retirement plans, and could opt out, participation rose sharply even though the available options had not changed at all.', 'Which choice best describes the overall structure of the text?', '["It describes an experiment, questions its methods, and calls for the experiment to be repeated.", "It compares two retirement plans and recommends the one with the higher rate of return.", "It explains a theory, summarizes criticism of it, and concludes that the theory should be retained without revision.", "It outlines a traditional assumption, describes findings that challenge it, and presents an approach that responds to those findings."]'::jsonb, 'D', 'The text moves from the calculation view to inconsistent behavior to Thaler’s automatic enrollment. It doesn’t keep the old theory, compare two plans’ returns, or question any methods.', 'hand-written'),
  ('text_structure', 'hard', 'Nineteenth-century editors of Emily Dickinson’s work smoothed her irregular rhymes and replaced her dashes with conventional punctuation, insisting that readers could not otherwise follow her meaning, a claim that says more about its authors than about the poems. When scholars restored the original manuscripts in the 1950s, readers proved perfectly capable of following her, and the disruptions the editors had removed came to be seen as central to her achievement.', 'Which choice best describes the function of the underlined portion, “a claim that says more about its authors than about the poems,” in the text as a whole?', '["It suggests that the editors were secretly the authors of some of Dickinson’s poems.", "It introduces evidence that the manuscripts of the poems were unreliable.", "It concedes that Dickinson’s meaning was difficult for readers to follow.", "It signals that the editors’ justification reflected their own assumptions rather than a real problem with the work."]'::jsonb, 'D', 'The phrase casts doubt on the editors’ reason by pointing back at them, and the next sentence confirms readers had no such problem. “Authors” refers to those who made the claim, not writers of the poems, which is the trap in the first wrong choice.', 'hand-written'),
  ('text_structure', 'hard', 'Studies of animal cognition have long been shaped by what is convenient to measure. Because mirror tests rely on vision, for example, they favor species that navigate primarily by sight, and animals that fail the test have sometimes been described as lacking self-recognition. Dogs, which rely heavily on smell, ignore their reflections, yet in a recent experiment they spent more time investigating their own scent when it had been altered than when it had not. Such results suggest that the absence of evidence in one sensory channel may reflect the limits of the test rather than the limits of the animal.', 'Which choice best states the main purpose of the text?', '["To claim that studies of animal cognition have not produced any useful results", "To explain the procedure researchers use to alter the scent of a dog", "To argue that a common test may misjudge animals whose main senses differ from the ones it relies on", "To show that dogs are more intelligent than other animals that have taken mirror tests"]'::jsonb, 'C', 'The final sentence states the point: failure on a vision-based test may reflect the test, not the animal. The text doesn’t rank dogs’ intelligence, and “not produced any useful results” goes much too far.', 'hand-written'),
  ('text_structure', 'hard', 'The rise of the novel in eighteenth-century England is often attributed to a growing middle class with time to read. This account has an obvious appeal, but it struggles to explain why readers in other prosperous societies of the period did not embrace long prose fiction with the same enthusiasm. Literary historians have therefore begun to look beyond leisure and income, examining instead the spread of circulating libraries, which lowered the cost of borrowing books, and the social habits that made reading aloud a shared household activity.', 'Which choice best describes the function of the second sentence in the text as a whole?', '["It rejects the idea that novels were widely read in eighteenth-century England.", "It introduces the claim that reading aloud was more popular than private reading.", "It provides additional evidence for the explanation presented in the first sentence.", "It identifies a weakness in the explanation presented in the first sentence, which motivates the approach described next."]'::jsonb, 'D', '“Struggles to explain” marks a weakness, and “therefore” in the next sentence shows it prompted a new approach. The sentence doesn’t deny that novels were read; it questions why.', 'hand-written'),
  ('cross_text', 'easy', 'Text 1
Homework adds stress to students’ lives and takes time away from family and sleep. Schools should stop assigning it entirely.

Text 2
Small amounts of homework can help students practice skills and build good habits. The problem is too much homework, not homework itself. Schools should keep assignments short.', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1 that homework should be eliminated?', '["By agreeing that all homework should end", "By arguing that homework should be reduced rather than eliminated", "By denying that students feel any stress", "By claiming that students need much more homework"]'::jsonb, 'B', 'Text 2 says the problem is “too much homework” and recommends short assignments, so it would favor reducing, not ending, homework.', 'hand-written'),
  ('cross_text', 'easy', 'Text 1
Electric scooters give city residents a cheap, clean way to travel short distances. They cut down on car trips and make it easier to reach bus and train stops.

Text 2
Electric scooters often clutter sidewalks and put pedestrians at risk. Many cities have seen injuries rise since rental scooters arrived.', 'Which choice best describes a difference in how the authors of Text 1 and Text 2 view electric scooters?', '["Both authors believe scooters should be banned immediately.", "Text 1 discusses injuries, while Text 2 discusses train stops.", "Text 1 focuses on their benefits, while Text 2 focuses on the problems they cause.", "Text 1 says they are expensive, while Text 2 says they are cheap."]'::jsonb, 'C', 'Text 1 lists advantages and Text 2 lists harms. The other choices swap details or claim a ban neither text proposes.', 'hand-written'),
  ('cross_text', 'easy', 'Text 1
For many years, scientists pictured dinosaurs as slow, cold-blooded reptiles that dragged their tails along the ground.

Text 2
Fossil trackways show almost no tail marks, and bone studies suggest many dinosaurs grew quickly, like birds. These findings point to active, warm-blooded animals.', 'Based on the texts, what would the author of Text 2 most likely say about the idea in Text 1 that dinosaurs were slow, cold-blooded reptiles?', '["It was never held by scientists.", "It is not supported by fossil evidence.", "It applies to birds but not to dinosaurs.", "It is supported by the bone studies."]'::jsonb, 'B', 'Text 2’s evidence points to active animals, which conflicts with the older picture. It doesn’t deny that scientists once believed it.', 'hand-written'),
  ('cross_text', 'easy', 'Text 1
Libraries should remove their print reference books. Nearly all of that information can now be found online, and the shelf space could be used for study rooms.

Text 2
Not every library visitor has reliable internet access at home, and many older adults prefer print. Libraries serve people best when they offer information in more than one form.', 'Based on the texts, how would the author of Text 2 most likely respond to the suggestion in Text 1?', '["By suggesting that libraries need fewer study rooms", "By arguing that online information is always inaccurate", "By agreeing that print books are no longer useful", "By pointing out that some library users still depend on print materials"]'::jsonb, 'D', 'Text 2 stresses visitors without internet and those who prefer print. It never discusses study rooms or the accuracy of online sources.', 'hand-written'),
  ('cross_text', 'medium', 'Text 1
A 2018 survey found that people who owned dogs reported better health than those who did not. The researchers concluded that owning a dog improves health, likely because dogs require daily walks.

Text 2
People who choose to adopt a dog may already be more active and financially stable than people who do not. Studies comparing dog owners with non-owners therefore cannot easily separate the effects of the dog from the traits of the people who own one.', 'Based on the texts, how would the author of Text 2 most likely respond to the conclusion in Text 1?', '["By cautioning that the health difference may reflect who chooses to own dogs rather than an effect of the dogs themselves", "By arguing that dog owners actually report worse health than non-owners", "By claiming that daily walks provide no health benefits", "By recommending that more people adopt dogs to improve their health"]'::jsonb, 'A', 'Text 2 raises a selection problem: owners may already differ from non-owners. It doesn’t dispute the survey’s results or say walking is useless.', 'hand-written'),
  ('cross_text', 'medium', 'Text 1
To protect rare seabirds on islands, conservationists often remove invasive rats. On many islands the bird populations have rebounded within a few years, making rat removal one of the most reliable tools in island conservation.

Text 2
Removing an invasive species can have unexpected effects. On one sub-Antarctic island, eliminating cats allowed rabbits to multiply, and the rabbits then stripped away much of the island’s vegetation. Managers must study how species interact before they act.', 'Based on the texts, how would the author of Text 2 most likely view the approach described in Text 1?', '["As potentially useful but in need of careful study of each island’s species beforehand", "As more effective on sub-Antarctic islands than anywhere else", "As harmful because seabirds never benefit from the removal of rats", "As unnecessary because invasive species rarely affect native birds"]'::jsonb, 'A', 'Text 2 doesn’t oppose removal outright; it warns of side effects and says managers must study interactions first. The other choices overstate or invent claims.', 'hand-written'),
  ('cross_text', 'medium', 'Text 1
The Silk Road is often imagined as a single road along which merchants carried goods all the way from China to Rome.

Text 2
Archaeological records reveal a web of shifting local routes. Most traders traveled only short distances, passing goods along to others at regional markets. Few individuals, if any, made the entire journey.', 'Which choice best describes how Text 2 relates to Text 1?', '["Text 2 provides an example that supports the image described in Text 1.", "Text 2 shows that the Silk Road did not carry any goods.", "Text 2 explains why merchants preferred Rome to China.", "Text 2 offers evidence that corrects the popular image described in Text 1."]'::jsonb, 'D', 'Text 1 describes how the road is “imagined,” and Text 2 replaces that with a web of short routes. Goods still moved, so the last choice goes too far.', 'hand-written'),
  ('cross_text', 'medium', 'Text 1
Four-day workweeks have raised morale at many companies. In trials, employees reported less burnout, and most firms saw no decline in output. More employers should adopt the schedule.

Text 2
The early trials of four-day workweeks are encouraging, since workers do report feeling better. But most participating firms volunteered, and they may not represent the economy as a whole. Hospitals and factories, for example, may find the schedule much harder to adopt.', 'Based on the texts, on which point would the authors of Text 1 and Text 2 most likely agree?', '["Output declined at most firms in the trials.", "The trials were limited to hospitals and factories.", "Employees in the trials reported benefits from a four-day workweek.", "Every employer should adopt a four-day workweek immediately."]'::jsonb, 'C', 'Both texts note better well-being among workers. Text 2 resists a universal adoption, and Text 1 says output held steady.', 'hand-written'),
  ('cross_text', 'hard', 'Text 1
The stone circles of Neolithic Britain were, according to many archaeologists, primarily astronomical instruments. The precise alignment of several monuments with the solstices demonstrates that their builders were systematically tracking the sun, and it suggests that the sites functioned as a kind of calendar for an agricultural society.

Text 2
Alignments are easy to find if one looks for them: with enough stones and enough celestial events, some matches will occur by chance. Even where an alignment was intended, it need not imply calendrical record keeping. A monument oriented toward the midwinter sunset may have marked a single annual ceremony, with the alignment serving ritual purposes rather than practical timekeeping.', 'Based on the texts, how would the author of Text 2 most likely respond to the interpretation in Text 1?', '["By contending that even a genuine alignment would not establish that the monuments were used to keep a calendar", "By denying that any Neolithic monument was built with the sun in mind", "By asserting that Neolithic societies did not depend on agriculture", "By arguing that the builders were more interested in the stars than in the sun"]'::jsonb, 'A', 'Text 2 grants that an alignment may be intended but says it could be ritual, not timekeeping. “Denying that any” is too strong because of “Even where an alignment was intended.”', 'hand-written'),
  ('cross_text', 'hard', 'Text 1
Critics who judge a translation only by its fidelity to the original miss what translation is for. A translator’s first obligation is to produce a work that lives in the new language, and this may require departing from the original’s exact wording, its sentence structure, even its images, when these would strike new readers as stilted.

Text 2
Translators who treat smoothness as their highest goal risk erasing what makes a foreign text foreign. If every strange turn of phrase is converted into something familiar, readers learn nothing about how another culture thinks. A good translation should leave some strangeness in place, even at the cost of a little awkwardness.', 'Based on the texts, how would the author of Text 1 most likely respond to the point made in the final sentence of Text 2?', '["By claiming that translators should stop translating images entirely", "By agreeing that a translator’s highest duty is to preserve the foreign text’s exact wording", "By arguing that foreign texts contain few phrases that seem strange to readers", "By maintaining that a translation that reads awkwardly fails in the translator’s primary duty, even if it preserves some strangeness"]'::jsonb, 'D', 'Text 1 ranks a living work in the new language first, so it would reject accepting awkwardness. It explicitly allows departures from exact wording, which rules out the first wrong choice.', 'hand-written'),
  ('cross_text', 'hard', 'Text 1
In a laboratory study, participants who had just read literary fiction scored higher on a test of recognizing others’ emotions than participants who had read popular fiction or nonfiction. The researchers concluded that reading literary fiction immediately improves a person’s capacity to understand other people.

Text 2
Several teams have tried to reproduce the short-term effect of literary fiction on emotion recognition, with mixed results. What has held up better is a correlation: people who read a great deal of fiction over a lifetime tend to score higher on such tests. Whether reading builds this ability, however, or whether perceptive people simply enjoy fiction more, remains an open question.', 'Based on the texts, what would the author of Text 2 most likely say about the researchers’ conclusion in Text 1?', '["It is confirmed by the correlation between lifetime reading and test scores.", "It is not well established, because the immediate effect has not been consistently reproduced.", "It applies only to people who read popular fiction rather than literary fiction.", "It is incorrect, because fiction readers score lower on tests of emotion recognition."]'::jsonb, 'B', 'Text 2 reports “mixed results” for the short-term effect. The correlation it describes is about lifetime reading, and it explicitly doesn’t prove cause, so it can’t confirm the immediate claim.', 'hand-written'),
  ('cross_text', 'hard', 'Text 1
The city’s plan to widen Route 9 rests on simple arithmetic. The road now carries more traffic than its two lanes can handle, and travel times have doubled in a decade. Adding two lanes will increase capacity by roughly 100 percent and restore the commute that residents once enjoyed.

Text 2
Transportation researchers have documented a pattern known as induced demand. When a road is widened, driving on it becomes temporarily easier, which draws drivers from other routes and other times of day and encourages new trips. In many metropolitan areas, traffic on expanded highways has returned to earlier levels of congestion within a few years.', 'Which choice best describes how the author of Text 2 would most likely regard the assumption underlying the policy in Text 1?', '["As irrelevant, because Route 9 is not a metropolitan highway", "As sound, because adding lanes reliably reduces congestion for many decades", "As outdated, because residents now commute less than they did a decade ago", "As flawed, because it treats the amount of traffic as fixed when added capacity tends to generate more driving"]'::jsonb, 'D', 'Text 1 assumes the same traffic spread over more lanes. Induced demand says more lanes bring more traffic, so that assumption is flawed. Text 2 says nothing about Route 9 specifically or about commuting declines.', 'hand-written'),
  ('central_ideas', 'easy', 'Lighthouses once needed keepers who lived on site and tended the lamps every night. Today, nearly all lighthouses run automatically. Sensors switch the lights on at dusk, and technicians visit only for repairs.', 'Which choice best states the main idea of the text?', '["Lighthouses that once required keepers now mostly operate on their own.", "Most lighthouses have been torn down.", "Technicians visit lighthouses every night.", "Lighthouse keepers enjoyed living near the sea."]'::jsonb, 'A', 'The text contrasts past keepers with today’s automatic lights. The other choices add details or contradict “only for repairs.”', 'hand-written'),
  ('central_ideas', 'easy', 'Mina’s grandmother taught her to fold dumplings when Mina was six. At first her dumplings fell apart in the pot. After many tries, she learned to pinch the edges tightly. Now she teaches her younger cousins the same way.', 'Which choice best states the main idea of the text?', '["Mina’s grandmother refuses to teach her cousins.", "Mina’s dumplings always fall apart in the pot.", "Mina learned a skill through practice and now passes it on.", "Mina does not enjoy cooking with her family."]'::jsonb, 'C', 'The text moves from her first failures to skill to teaching others. Her dumplings fell apart only “at first.”', 'hand-written'),
  ('central_ideas', 'easy', 'Plants in a city can do more than look nice. Trees shade streets and buildings, which lowers summer temperatures. Their leaves trap dust, and their roots absorb rainwater that might otherwise flood roads.', 'Which choice best states the main idea of the text?', '["City trees are difficult to keep alive.", "Flooding is the worst problem in most cities.", "Plants in cities are mainly decorative.", "City plants provide several practical benefits."]'::jsonb, 'D', 'The text lists cooling, cleaner air, and flood control as benefits. It says plants do “more than look nice,” which contradicts “mainly decorative.”', 'hand-written'),
  ('central_ideas', 'easy', 'The Great Wall of China is not one continuous wall. It is a series of walls and forts built by different dynasties over about two thousand years. Some sections are made of stone or brick, while others are packed earth.', 'Which choice best states the main idea of the text?', '["The forts along the wall are older than the walls.", "The Great Wall was finished in a single dynasty.", "The Great Wall is really many structures built at different times.", "Stone is the only material used in the Great Wall."]'::jsonb, 'C', 'The main point is that it isn’t one wall but many sections built over time. Each wrong choice contradicts a detail or adds one that isn’t there.', 'hand-written'),
  ('central_ideas', 'medium', 'When ecologists reintroduced beavers to a stretch of river in Scotland, they expected changes in the water but not on the scale that followed. The dams slowed the current and created ponds that held back floodwater after heavy rain. Dragonflies, frogs, and water birds moved into the new wetlands within a few seasons, and water leaving the area was noticeably cleaner than water arriving.', 'Which choice best states the main idea of the text?', '["Scottish ecologists were disappointed by how slowly the wetlands appeared.", "Dragonflies and frogs are the species most dependent on beaver dams.", "Beaver dams cause more flooding after heavy rain than natural rivers do.", "Returning beavers to the river reshaped the area in ways that benefited both water and wildlife."]'::jsonb, 'D', 'The text lists flood control, new wildlife, and cleaner water, all from the beavers’ return. Dams reduced flooding, and no ranking of species is offered.', 'hand-written'),
  ('central_ideas', 'medium', 'The following text is adapted from a novel. Lena has returned to her childhood town after many years.

The bakery had a new sign, and the old oak by the school was gone, but what unsettled Lena most was how small everything looked. The hill she had once dreaded on her bicycle was hardly a slope. She stood at the bottom of it for some time, trying to feel the size of what she remembered.', 'Which choice best states the main idea of the text?', '["Lena regrets having left her town at a young age.", "Lena is struck by how different the town seems from her memories of it.", "Lena plans to ride her bicycle up the hill again.", "Lena is angry that the old oak has been cut down."]'::jsonb, 'B', 'The passage focuses on the gap between memory and reality: “how small everything looked.” Regret, anger, and plans go beyond what’s stated.', 'hand-written'),
  ('central_ideas', 'medium', 'Most museums display only a small fraction of what they own; the rest sits in storage. A growing number of institutions are responding by building “visible storage,” in which shelves of objects can be seen through glass by anyone who walks by. Curators say these spaces reveal how collections are actually organized and invite visitors to find objects no exhibit would have chosen for them.', 'Which choice best states the main idea of the text?', '["Some museums are making stored objects viewable, which offers visitors a new way of experiencing collections.", "Curators believe exhibits should no longer select objects for display.", "Museums have run out of space because they own too many objects.", "Glass storage protects objects better than traditional storage rooms."]'::jsonb, 'A', 'The text is about visible storage and what it offers visitors. It doesn’t say exhibits should end or compare protection.', 'hand-written'),
  ('central_ideas', 'medium', 'Sleep researchers once treated dreaming as a by-product of random brain activity. Later studies complicated that view. People who practiced a new task and then dreamed about it improved more on the task the next day than those who practiced but didn’t dream about it. Researchers caution that the link isn’t fully understood, but such results suggest that dreaming may play some role in learning.', 'Which choice best states the main idea of the text?', '["Dreaming has been proven to be the main way people learn new tasks.", "Evidence suggests dreaming may contribute to learning, though the connection remains uncertain.", "People who dream less have more difficulty sleeping at night.", "Random brain activity is unrelated to the sleeping brain."]'::jsonb, 'B', '“May play some role” and “isn’t fully understood” call for a cautious statement. “Proven” and “the main way” are far too strong.', 'hand-written'),
  ('central_ideas', 'hard', 'The notion that Renaissance painters abruptly discovered perspective through mathematics has given way to a more gradual account. Workshop records show that artists experimented for decades with practical devices, including grids and mirrors, well before any theory was written down. Treatises such as Alberti’s, on this view, did less to invent a new technique than to organize and lend intellectual prestige to methods already circulating among craftsmen.', 'Which choice best states the main idea of the text?', '["Renaissance painters rejected mathematics in favor of mirrors and grids.", "Perspective developed through artists’ practical experimentation, with written theory later codifying it rather than creating it.", "Alberti’s treatise was largely ignored by the craftsmen of his own time.", "Written theories of perspective led directly to the workshop experiments."]'::jsonb, 'B', 'The point is that practice came first and treatises organized it. The last choice reverses the order, and the text never says painters rejected math or that Alberti was ignored.', 'hand-written'),
  ('central_ideas', 'hard', 'The following text is adapted from an essay on the novelist George Eliot.

Eliot’s narrators seldom let a character’s failing pass without comment, and readers might expect such attention to harden into judgment. It doesn’t. Her habit is to follow the most self-deceiving character into the private reasoning that made the error seem sensible, so that condemnation becomes difficult. The reader who begins by feeling superior to a vain clergyman finishes by recognizing how ordinary his vanity is, and how close to one’s own.', 'Which choice best states the main idea of the text?', '["Eliot’s novels mainly criticize the clergymen of her time.", "Eliot’s narrators refuse to comment on the moral failings of their characters.", "Eliot’s close attention to characters’ flaws leads readers toward understanding rather than condemnation.", "Eliot’s characters come to recognize their errors by the end of each novel."]'::jsonb, 'C', 'The essay says her attention doesn’t “harden into judgment” and leads to recognition. Narrators do comment, and it’s the reader, not the character, who recognizes something.', 'hand-written'),
  ('central_ideas', 'hard', 'Public discussions of recycling often assume that the chief obstacle is consumer behavior: if people sorted more carefully, more material would be reused. Yet studies of municipal systems point elsewhere. Much of what residents place in bins cannot be profitably processed, because the market for recovered plastics fluctuates with the price of oil, and new plastic is frequently cheaper than reclaimed material. Even perfectly sorted waste, in other words, may end up in a landfill when no one will pay to take it.', 'Which choice best states the main idea of the text?', '["Consumers are sorting their waste more carefully than they did in the past.", "Municipal recycling systems are unnecessary because most waste ends up in landfills.", "Recycling outcomes depend heavily on economic conditions, not just on how well consumers sort their waste.", "Plastic should be replaced by other materials that are more easily recycled."]'::jsonb, 'C', 'The text shifts attention from sorting to markets and prices. It makes no claim about trends in sorting, replacing plastic, or ending recycling programs.', 'hand-written'),
  ('central_ideas', 'hard', 'Early accounts of the Dust Bowl presented it as a natural disaster, a drought of unusual severity striking the Great Plains in the 1930s. Later historians have argued that this framing obscures human choices. Decades of plowing had stripped away the deep-rooted grasses that once anchored the soil, and federal land policy, along with high wheat prices, had encouraged that expansion. The drought was real, these historians grant, but it became catastrophic only on land already made vulnerable.', 'Which choice best states the main idea of the text?', '["Farmers on the Great Plains opposed federal land policy in the 1930s.", "The drought of the 1930s was less severe than early accounts claimed.", "The Dust Bowl resulted from the interaction of drought with earlier farming practices and policies.", "High wheat prices were the main reason that the drought occurred."]'::jsonb, 'C', '“The drought was real... but it became catastrophic only on land already made vulnerable” shows both causes working together. The text doesn’t question its severity, and prices didn’t cause the drought.', 'hand-written'),
  ('evidence_textual', 'easy', 'In a poem by Rosa Lind, the speaker views the sea as peaceful.', 'Which quotation from the poem most effectively illustrates this claim?', '["“The market fills with fish and salt, / and shouting fills the air.”", "“The storm tears ships apart at night / and howls along the shore.”", "“The waves breathe softly on the sand, / a slow and quiet tune.”", "“I left my village long ago / and never sailed again.”"]'::jsonb, 'C', 'Soft breathing and a quiet tune show a peaceful sea. The storm is violent, and the other two aren’t about the sea’s calm.', 'hand-written'),
  ('evidence_textual', 'easy', 'A high school track coach claims that students who get at least eight hours of sleep run faster in practice than students who get less sleep.', 'Which finding, if true, would most directly support the coach’s claim?', '["Runners who slept eight or more hours had faster practice times than those who slept less.", "Runners who ate breakfast were more likely to attend practice.", "Most students at the school do not get eight hours of sleep.", "Practice times were faster on cool days than on hot days."]'::jsonb, 'A', 'Only this finding links sleep amount to running speed. The other choices involve breakfast, general habits, or weather.', 'hand-written'),
  ('evidence_textual', 'easy', 'A student hypothesizes that tomato plants grown with music will grow taller than tomato plants grown in silence.', 'Which finding, if true, would most directly support the hypothesis?', '["Students enjoyed playing music in the greenhouse.", "Tomato plants in a room with music grew taller than plants in a quiet room.", "Tomato plants grew taller with more sunlight.", "Tomato plants in the quiet room produced the same amount of fruit."]'::jsonb, 'B', 'The hypothesis compares height with and without music, so that comparison is the direct support.', 'hand-written'),
  ('evidence_textual', 'easy', 'In a letter, the nineteenth-century traveler Clara Wells shows how tired she has grown of her long journey by stagecoach.', 'Which quotation from the letter most effectively illustrates the claim?', '["“I have counted every mile, and I would give a year of my life to sleep in a still bed.”", "“My sister writes that the harvest was good this year.”", "“The mountains here are the finest I have ever seen.”", "“We shall reach the river by Tuesday, the driver says.”"]'::jsonb, 'A', 'Counting miles and longing for a still bed show weariness. The others are simple observations or news.', 'hand-written'),
  ('evidence_textual', 'medium', 'Some songbirds sing at a higher pitch in cities than in the countryside. Biologist Hana Tanaka hypothesizes that this is because low-pitched traffic noise drowns out lower notes, so birds that sing higher are heard more easily by mates and rivals.', 'Which finding, if true, would most directly support Tanaka’s hypothesis?', '["Within the same city, birds of a given species sing at a higher pitch near busy roads than in quiet parks.", "Birds in cities begin singing earlier in the morning than birds in the countryside.", "Birds that live in the countryside tend to have larger territories than city birds.", "Traffic noise in cities has increased steadily over the past fifty years."]'::jsonb, 'A', 'Tying pitch directly to noise levels, in the same city, tests her explanation. Timing, noise trends alone, and territory size don’t link noise to pitch.', 'hand-written'),
  ('evidence_textual', 'medium', 'Researchers studying a small island’s forest claim that the decline of a native fruit-eating bird has reduced the spread of a certain tree, since the bird was the main animal that carried the tree’s seeds to new sites.', 'Which finding, if true, would most directly weaken the researchers’ claim?', '["The tree’s fruit ripens during the season when the bird is most active.", "Young trees of that species are appearing at new sites at the same rate as before the bird declined.", "The bird’s decline began shortly after a new predator arrived on the island.", "Several other tree species on the island also produce fruit eaten by the bird."]'::jsonb, 'B', 'If the tree keeps spreading at the same rate, the bird’s decline hasn’t reduced it. The other findings don’t bear on whether seed spread has fallen.', 'hand-written'),
  ('evidence_textual', 'medium', 'In a 1920s novel by Adele Marsh, the narrator suggests that the character Mr. Hollis cares more about how he appears to others than about the truth.', 'Which quotation from the novel most effectively illustrates the claim?', '["“Hollis had inherited the house from an uncle he barely knew.”", "“Hollis walked each morning to the post office, whatever the weather.”", "“Hollis would rather be admired for a falsehood than go unnoticed for an honest remark.”", "“Hollis spoke rarely, and when he did it was usually about his garden.”"]'::jsonb, 'C', 'This line directly compares admiration with honesty. The others are neutral details about his habits and history.', 'hand-written'),
  ('evidence_textual', 'medium', 'A team of nutrition researchers argues that a town’s new farmers’ market, rather than a general trend, was responsible for the increase in fruit and vegetable purchases among the town’s residents after the market opened in 2021.', 'Which finding, if true, would most directly support the claim?', '["Fruit and vegetable prices at the market were similar to those at local supermarkets.", "Residents reported that they enjoyed the live music played at the market.", "The market was located near the town’s largest public park.", "Purchases rose in the town after 2021 but stayed flat in similar nearby towns without new markets."]'::jsonb, 'D', 'Comparing with similar towns rules out a general trend, which is exactly what the claim needs. The other choices don’t address cause.', 'hand-written'),
  ('evidence_textual', 'hard', 'Economist Ngozi Okafor studied a city that raised its minimum wage in 2016. Restaurant employment there grew over the next three years, and Okafor concluded that the increase did not reduce restaurant jobs. Critics note that the city’s population was growing rapidly over the same period, so restaurant jobs might have grown even without the wage increase, and perhaps faster.', 'Which finding, if true, would most directly undermine Okafor’s conclusion?', '["Restaurants in the city raised their menu prices slightly in the years after 2016.", "Employment in the city’s other industries also increased between 2016 and 2019.", "Workers in the city reported higher satisfaction with their jobs after the wage increase.", "In comparable fast-growing cities with no wage increase, restaurant employment rose substantially more than it did in the city Okafor studied."]'::jsonb, 'D', 'If similar cities gained more jobs without the increase, the raise may have held employment back. Higher prices or other industries’ growth don’t show that restaurant jobs were reduced.', 'hand-written'),
  ('evidence_textual', 'hard', 'In an essay, the critic Helen Brandt argues that the value of a difficult book lies in the effort of reading it, and not merely in the ideas that a summary could convey.', 'Which quotation from the essay most effectively illustrates the claim?', '["“The conclusions of a difficult book are usually simpler than its admirers are willing to admit.”", "“Few modern novels reward the attention of readers as generously as those of the last century.”", "“A summary may often be more accurate than the opinions of those who have read a book too quickly.”", "“What the slow reader carries away is not a set of conclusions, which any synopsis could supply, but a mind altered by the labor of arriving at them.”"]'::jsonb, 'D', 'This quotation names both parts of the claim: a synopsis gives conclusions, while the labor itself changes the reader. The others touch on summaries or difficulty but don’t say value lies in the effort.', 'hand-written'),
  ('evidence_textual', 'hard', 'Fossil beds show that a group of large marine reptiles disappeared some 90 million years ago, a time of rapid warming and low oxygen in deep ocean water. Some researchers argue that the reptiles were not killed directly by these conditions. Instead, they propose, the low-oxygen water reduced the populations of deep-dwelling squid-like animals on which the reptiles depended, leaving them without enough to eat.', 'Which finding, if true, would most directly support the researchers’ explanation?', '["Other marine reptiles that fed near the surface vanished at the same moment as the deep-feeding group.", "Ocean temperatures rose more quickly in that period than in any earlier period.", "Fossils of the reptiles’ deep-dwelling prey decline sharply in rock layers immediately below the layers in which the reptiles themselves vanish.", "The reptiles’ bones show adaptations that would have let them tolerate warm water."]'::jsonb, 'C', 'Prey dropping first fits the food-chain explanation. Surface feeders vanishing at the same moment would point away from that explanation, and heat tolerance alone doesn’t show that prey loss was the cause.', 'hand-written'),
  ('evidence_textual', 'hard', 'A historian argues that the sharp rise in literacy in one European region between 1650 and 1750 resulted mainly from Protestant churches’ demand that members read scripture, rather than from economic growth in the region’s towns.', 'Which finding, if true, would most directly challenge the historian’s argument?', '["Many of the region’s Protestant churches established schools during the period.", "Printing costs fell steadily across all of Europe between 1650 and 1750.", "Literacy rates were higher among men than among women throughout the period.", "Within the region, literacy rose as fast in Catholic towns with growing trade as in Protestant towns, and slowly in poorer Protestant villages."]'::jsonb, 'D', 'This pattern tracks trade rather than religion, the opposite of the argument. Church schools would support it, and gender gaps don’t bear on the cause.', 'hand-written'),
  ('evidence_quantitative', 'easy', 'Books Borrowed from the Oakdale Library
Month | Fiction | Nonfiction
June | 420 | 310
July | 510 | 290
August | 480 | 300

The librarian noticed that summer readers preferred fiction. In every month shown, ______', 'Which choice most effectively uses data from the table to complete the statement?', '["more nonfiction books were borrowed than fiction books.", "more fiction books were borrowed than nonfiction books.", "the number of fiction books borrowed decreased each month.", "the number of nonfiction books borrowed was above 400."]'::jsonb, 'B', 'Fiction is higher in June, July, and August. Nonfiction stays near 300, and fiction rose in July.', 'hand-written'),
  ('evidence_quantitative', 'easy', 'Average Daily Temperature (°F) by City
City | January | July
Seattle | 42 | 66
Miami | 68 | 84
Denver | 32 | 75

A student claims that of the three cities, Denver has the largest temperature change between January and July.', 'Which choice most effectively uses data from the table to support the student’s claim?', '["Denver’s temperature rises by 43 degrees, compared with 24 degrees in Seattle and 16 degrees in Miami.", "Seattle’s July temperature is 66 degrees, the lowest of the three cities.", "Miami has the highest temperature in both January and July.", "Denver’s January temperature is 32 degrees, the lowest of the three cities."]'::jsonb, 'A', 'The claim is about the change, so the differences must be compared: 43, 24, and 16. The other choices give single temperatures.', 'hand-written'),
  ('evidence_quantitative', 'medium', 'Pollinator Visits per Hour to Garden Plots
Plot type | Bees | Butterflies | Flies
Native flowers | 34 | 12 | 9
Ornamental flowers | 15 | 11 | 10
Mixed flowers | 26 | 12 | 9

Researchers concluded that planting native flowers particularly benefits bees, while it makes little difference for other pollinators.', 'Which choice most effectively uses data from the table to support the researchers’ conclusion?', '["Mixed flower plots received 26 bee visits per hour and 9 fly visits per hour.", "Butterfly visits were highest in plots with native and mixed flowers, at 12 visits per hour.", "Bee visits were more than twice as frequent in native plots as in ornamental plots, while butterfly and fly visits were about the same across plot types.", "Bees made more visits than butterflies and flies in every type of plot."]'::jsonb, 'C', 'The conclusion has two parts: a big gain for bees and little change for others. Only the correct choice addresses both. The others are true of the table but miss that comparison.', 'hand-written'),
  ('evidence_quantitative', 'medium', 'Share of Trips Made by Bicycle (%)
City | 2010 | 2020
Amsel | 12 | 19
Brookton | 4 | 5
Corvale | 8 | 16

Cities that built protected bike lanes during the decade often saw large increases in cycling. Corvale, which built such lanes, offers an example: ______', 'Which choice most effectively uses data from the table to complete the example?', '["its share of bicycle trips was higher than Brookton’s in 2010.", "the share of trips made by bicycle in Brookton rose by only 1 percentage point.", "the share of trips made by bicycle there doubled from 8 percent to 16 percent.", "its share of bicycle trips in 2020 was lower than Amsel’s share."]'::jsonb, 'C', 'A large increase in Corvale is the needed example, and doubling shows it. Comparisons with other cities at one moment don’t show an increase there.', 'hand-written'),
  ('evidence_quantitative', 'hard', 'Survey of Adults Who Read at Least One Book in the Past Year (%)
Age group | 2012 | 2022
18–29 | 71 | 69
30–49 | 68 | 66
50–64 | 66 | 58
65+ | 63 | 52

A columnist claims that book reading is declining mainly because young adults spend their time on phones instead.', 'Which choice most effectively uses data from the table to weaken the claim?', '["Reading declined in every age group between 2012 and 2022.", "In both 2012 and 2022, adults aged 18–29 were the group most likely to have read a book.", "More than half of adults in every age group had read a book in 2022.", "The two oldest age groups had the largest declines, while reading among adults aged 18–29 fell by only 2 percentage points."]'::jsonb, 'D', 'If the decline is mainly due to the young, they should show the biggest drop, but the oldest groups do. A decline in every group doesn’t separate who drives it.', 'hand-written'),
  ('evidence_quantitative', 'hard', 'Effect of Two Fertilizers on Wheat Trial Plots
Treatment | Yield (tons per hectare) | Nitrogen lost to runoff (kg per hectare)
No fertilizer | 3.1 | 4
Fertilizer A | 5.2 | 31
Fertilizer B | 4.9 | 12

An agronomist argues that Fertilizer B is the better choice for farms near rivers, since ______', 'Which choice most effectively uses data from the table to complete the statement?', '["Fertilizer A produced the highest yield of the three treatments.", "the plots that received no fertilizer lost the least nitrogen to runoff.", "it produced nearly the same yield as Fertilizer A while losing well under half as much nitrogen to runoff.", "it produced a higher yield than the plots that received no fertilizer."]'::jsonb, 'C', 'Near rivers, runoff matters, and B must be compared with A on both yield and runoff: 4.9 versus 5.2 tons, 12 versus 31 kg. The other choices are true but don’t show B is better than A.', 'hand-written'),
  ('inferences', 'easy', 'Ravi noticed that the plants on his sunny windowsill were growing quickly, while the same kind of plants on a dark shelf had stopped growing. He concluded that ______', 'Which choice most logically completes the text?', '["the plants on the windowsill needed less water.", "the shelf was too warm for any plant.", "the plants on the windowsill were a different kind.", "the plants on the shelf needed more light."]'::jsonb, 'D', 'The only stated difference is light, and the plants are the same kind, so lack of light is the logical conclusion.', 'hand-written'),
  ('inferences', 'easy', 'Every student who attended the review session on Tuesday passed the quiz. Julia failed the quiz. Therefore, Julia ______', 'Which choice most logically completes the text?', '["took the quiz on Wednesday.", "did not attend the review session on Tuesday.", "attended the review session on Tuesday.", "studied more than the other students."]'::jsonb, 'B', 'All attendees passed, so anyone who failed cannot have attended.', 'hand-written'),
  ('inferences', 'easy', 'Old maps of the village show a river running along Main Street. Today there is no river there, but the houses on Main Street still flood during storms, and water pipes must be placed unusually deep. This suggests that ______', 'Which choice most logically completes the text?', '["storms in the village have stopped in recent years.", "the houses on Main Street were built before the village existed.", "the old maps were drawn by people who had never seen the village.", "the river may still be affecting the land beneath the street."]'::jsonb, 'D', 'Flooding and deep pipes along the old course point to the river’s continuing influence.', 'hand-written'),
  ('inferences', 'easy', 'Squirrels bury far more nuts than they later dig up. Some of the forgotten nuts sprout in spring. As a result, squirrels ______', 'Which choice most logically completes the text?', '["usually starve during the winter months.", "help new trees grow without intending to.", "prevent oak forests from spreading.", "eat only nuts that have already sprouted."]'::jsonb, 'B', 'Forgotten nuts sprout into trees, so the squirrels unintentionally plant them.', 'hand-written'),
  ('inferences', 'medium', 'The ancient city of Ubar appears in many old stories, but for centuries no one could locate it. In the 1990s, satellite images revealed faint caravan tracks in the Arabian desert that all met at one point. Since the tracks seem to have been made by traders traveling to a common destination, researchers reasoned that ______', 'Which choice most logically completes the text?', '["traders avoided settlements when crossing the desert.", "the meeting point of the tracks might mark the location of a major settlement.", "the old stories about Ubar were invented by the traders themselves.", "satellite images are more reliable than archaeological digging."]'::jsonb, 'B', 'Routes that converge on one point suggest a destination, likely a settlement. The other choices aren’t supported by the tracks.', 'hand-written'),
  ('inferences', 'medium', 'In a study of a fishing community, researchers found that older fishers could predict weather changes with accuracy close to that of local forecasts, relying on cloud shapes and bird behavior. Younger fishers, who use phone apps, could not do the same when asked to rely on observation alone. These findings suggest that ______', 'Which choice most logically completes the text?', '["younger fishers go out to sea less often than older fishers do.", "reliance on technology may be reducing a kind of knowledge that was once common in the community.", "phone apps are less accurate than the observations of older fishers.", "birds change their behavior in response to local weather forecasts."]'::jsonb, 'B', 'Older skill plus younger reliance on apps suggests the skill is fading. The study found observation was close to forecasts, not better than them.', 'hand-written'),
  ('inferences', 'medium', 'A chemist testing a new battery material found that it stored more energy than current materials but lost its capacity after a few dozen charges. Because consumers expect phone batteries to last for hundreds of charges, the chemist concluded that ______', 'Which choice most logically completes the text?', '["the material would need to become far more durable before it could be used in phones.", "the material could immediately replace current phone batteries.", "consumers would prefer phones that stored less energy.", "phone batteries are charged less often than they once were."]'::jsonb, 'A', 'A few dozen charges falls short of hundreds, so durability must improve before use.', 'hand-written'),
  ('inferences', 'medium', 'Paintings by the Dutch artist Judith Leyster were sold for centuries under the name of her better-known contemporary Frans Hals. Only in 1893, when a dealer’s dispute led experts to examine one painting closely and find her monogram beneath a forged signature, did her work begin to be recognized. This episode suggests that ______', 'Which choice most logically completes the text?', '["Leyster’s paintings were less skillful than those of Frans Hals.", "some artists’ reputations have been shaped by misattribution as well as by the quality of their work.", "most Dutch paintings of the period carry forged signatures.", "art dealers in the 1800s were unwilling to sell Dutch paintings."]'::jsonb, 'B', 'Her work went unrecognized because it was credited to Hals, showing that misattribution shaped her reputation. “Most” paintings overgeneralizes from one case.', 'hand-written'),
  ('inferences', 'hard', 'Many species of deep-sea fish produce their own light, and for decades biologists assumed that this ability had evolved only a few times. A recent analysis of fish genomes, however, indicates that bioluminescence arose independently at least twenty-five times. Because a trait that appears repeatedly in unrelated lineages is likely to offer a substantial advantage in the conditions those lineages share, the analysis implies that ______', 'Which choice most logically completes the text?', '["producing light is probably of considerable value to survival in the deep sea.", "fish living near the surface are unable to develop any form of bioluminescence.", "the earliest bioluminescent fish were the ancestors of all living deep-sea species.", "the genes responsible for bioluminescence are identical in all light-producing fish."]'::jsonb, 'A', 'The text’s general rule says repeated evolution implies an advantage in shared conditions, and these fish share the deep sea. Independent origins contradict a single ancestor and identical genes.', 'hand-written'),
  ('inferences', 'hard', 'Medieval manuscripts sometimes contain marginal drawings of knights fighting giant snails, images that have puzzled scholars for generations. One proposal held that the snails symbolized a particular enemy of the Church, but the images appear in manuscripts from regions and decades in which that enemy played no role. Since a symbol tied to a specific historical group would not be expected to appear where that group was unknown, the proposal ______', 'Which choice most logically completes the text?', '["proves that the drawings were intended as jokes by the scribes who made them.", "correctly explains why medieval artists enjoyed drawing animals in general.", "shows that the images were copied from a single lost manuscript.", "seems unable to account for the full range of manuscripts in which the images appear."]'::jsonb, 'D', 'The argument says the symbol’s distribution doesn’t match where that group mattered, so the proposal can’t explain all cases. Disproving one idea doesn’t prove jokes or a lost source.', 'hand-written'),
  ('inferences', 'hard', 'In many languages, words for “mother” contain the sound m, a pattern that once led some linguists to propose a shared ancient origin. Others note that m is among the easiest sounds for infants to produce, since it requires only closing the lips while vocalizing, and that parents tend to interpret a baby’s earliest syllables as referring to them. If this second account is correct, then the similarity among these words ______', 'Which choice most logically completes the text?', '["would be expected only among languages that are closely related.", "must have spread from one language to another through trade.", "shows that infants learn to speak earlier than linguists once believed.", "could have arisen independently in many languages rather than indicating a common ancestor."]'::jsonb, 'D', 'If infants’ physiology produces the pattern everywhere, no shared origin or borrowing is needed. Closely related languages wouldn’t be required.', 'hand-written'),
  ('inferences', 'hard', 'When a large employer in one town offered free bus passes to its staff, car commuting there fell. Planners in a neighboring town copied the program but saw no change, even though its staff were offered the same passes. The first town, however, had frequent bus service throughout the day, whereas buses in the second town ran only twice each morning. Taken together, these facts suggest that ______', 'Which choice most logically completes the text?', '["free bus passes reduce car commuting wherever they are offered.", "employers should not be expected to pay for their workers’ commuting costs.", "the cost of a bus trip may matter less to commuters than whether buses run often enough to be convenient.", "workers in the second town were less concerned about the cost of commuting."]'::jsonb, 'C', 'The same free passes worked only where service was frequent, so frequency appears to be what mattered. The second town’s result contradicts “wherever they are offered.”', 'hand-written'),
  ('boundaries', 'easy', 'The hikers reached the lake at noon ______ they ate lunch on the rocks by the shore.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["noon and", "noon,", "noon and,", "noon, and"]'::jsonb, 'D', 'Two complete sentences joined by “and” need a comma before “and.” A comma alone creates a comma splice.', 'hand-written'),
  ('boundaries', 'easy', 'Our science class visited the planetarium ______ the students learned how to find the North Star.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["planetarium, where", "planetarium; where", "planetarium where,", "planetarium. Where"]'::jsonb, 'A', '“Where the students learned...” is a dependent clause, so it attaches with a comma. A semicolon or period would leave a fragment.', 'hand-written'),
  ('boundaries', 'easy', 'Before the concert began ______ the musicians tuned their instruments backstage.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["began;", "began,", "began:", "began"]'::jsonb, 'B', 'An introductory clause is followed by a comma. A semicolon or colon needs a complete sentence before it.', 'hand-written'),
  ('boundaries', 'easy', 'The recipe calls for three ingredients ______ flour, butter, and sugar.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["ingredients;", "ingredients, and", "ingredients. Flour,", "ingredients:"]'::jsonb, 'D', 'A colon introduces a list after a complete sentence. A semicolon needs a full sentence after it, too.', 'hand-written'),
  ('boundaries', 'easy', 'My sister plays the violin ______ my brother plays the drums.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["violin", "violin and,", "violin,", "violin;"]'::jsonb, 'D', 'A semicolon can join two complete sentences. A comma alone makes a comma splice, and no punctuation makes a run-on.', 'hand-written'),
  ('boundaries', 'easy', 'The library, which opened in 1925 ______ is the oldest building on campus.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1925", "1925,", "1925;", "1925:"]'::jsonb, 'B', 'The extra information needs a closing comma to match the one after “library.”', 'hand-written'),
  ('boundaries', 'easy', 'The storm knocked down several trees ______ workers cleared the road by morning.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["trees but,", "trees; but", "trees,", "trees, but"]'::jsonb, 'D', 'A comma plus “but” correctly joins two complete sentences. A comma alone is a splice.', 'hand-written'),
  ('boundaries', 'easy', 'Sara packed a jacket ______ she expected cold weather in the mountains.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["jacket: because", "jacket because", "jacket. Because", "jacket; because"]'::jsonb, 'B', '“Because she expected...” is dependent, so it can’t stand after a period or semicolon. No punctuation is needed.', 'hand-written'),
  ('boundaries', 'medium', 'Astronomer Vera Rubin measured how quickly stars orbit the centers of galaxies ______ her data revealed that the stars moved too fast to be held in place by visible matter alone, providing key evidence for dark matter.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["galaxies, that", "galaxies,", "galaxies;", "galaxies"]'::jsonb, 'C', 'Both sides are complete sentences, so a semicolon works. A comma alone is a splice, and no punctuation is a run-on.', 'hand-written'),
  ('boundaries', 'medium', 'The Inca built roads across the Andes without iron tools or wheeled vehicles ______ many of those roads, paved with fitted stone, are still walkable today.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["vehicles; and,", "vehicles, and", "vehicles and,", "vehicles,"]'::jsonb, 'B', 'A comma before “and” joins two complete sentences. The other choices either splice or misplace the comma.', 'hand-written'),
  ('boundaries', 'medium', 'Mae Jemison, the first Black woman to travel in space ______ also trained as a physician and worked in the Peace Corps before joining NASA.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["space;", "space:", "space", "space,"]'::jsonb, 'D', 'The appositive needs a closing comma to match the one after “Jemison.” The sentence’s verb is “trained.”', 'hand-written'),
  ('boundaries', 'medium', 'Although octopuses are solitary animals for most of their lives ______ researchers have occasionally observed them gathering in dense groups near rich food sources.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["lives:", "lives,", "lives.", "lives;"]'::jsonb, 'B', '“Although...” is a dependent clause, so a comma connects it. A semicolon, period, or colon would leave it stranded as a fragment.', 'hand-written'),
  ('boundaries', 'medium', 'The museum’s newest exhibit features works by three sculptors: Ruth Asawa, known for her looped wire forms ______ Isamu Noguchi, who designed gardens as well as sculptures; and Augusta Savage, a leader of the Harlem Renaissance.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["forms:", "forms,", "forms", "forms;"]'::jsonb, 'D', 'Items in this list contain internal commas, so semicolons separate them. The later items use a semicolon, and this one must match.', 'hand-written'),
  ('boundaries', 'medium', 'Sound travels about four times faster in water than in air ______ whales can communicate across hundreds of miles of ocean.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["air, so", "air so,", "air; so,", "air,"]'::jsonb, 'A', '“So” here joins two complete sentences and needs a comma before it, not after it.', 'hand-written'),
  ('boundaries', 'medium', 'Maria Tallchief became the first American prima ballerina of the New York City Ballet in 1947 ______ performance in The Firebird two years later made her internationally famous.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1947 her", "1947, her", "1947, and, her", "1947; her"]'::jsonb, 'D', 'Two complete sentences must be separated. A semicolon does this; a comma alone is a splice, and no punctuation is a run-on.', 'hand-written'),
  ('boundaries', 'medium', 'The bridge’s designers tested a scale model in a wind tunnel ______ a step that revealed a dangerous vibration long before construction began.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["tunnel,", "tunnel;", "tunnel.", "tunnel"]'::jsonb, 'A', '“A step that revealed...” is not a complete sentence; it renames the action before it, so it attaches with a comma.', 'hand-written'),
  ('boundaries', 'hard', 'For centuries, sailors crossing the Pacific relied on stick charts, lattices of palm ribs and shells used by Marshall Islanders to represent how ocean swells bend around islands ______ these charts were memorized before departure and never carried on the voyage itself, which meant that a navigator’s most essential instrument was his own trained recall.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["islands,", "islands, these", "islands;", "islands"]'::jsonb, 'C', 'The clause beginning “these charts were memorized” is a complete sentence, as is the first part. A semicolon separates them; a comma makes a splice, however long the sentences are.', 'hand-written'),
  ('boundaries', 'hard', 'The novelist Toni Morrison, who worked for years as an editor at Random House while raising two children and writing in the early mornings ______ published her first book, The Bluest Eye, in 1970.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["mornings;", "mornings,", "mornings", "mornings—"]'::jsonb, 'B', 'The long “who” clause opened with a comma, so it must close with one. The verb “published” is far from its subject “Toni Morrison,” which hides the need.', 'hand-written'),
  ('boundaries', 'hard', 'Marine geologist Marie Tharp spent years plotting depth measurements by hand ______ when her finished map of the Atlantic floor revealed a vast rift valley running along the mid-ocean ridge, it gave crucial support to the then-controversial theory of continental drift.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["hand;", "hand", "hand,", "hand, and,"]'::jsonb, 'A', 'Both sides are complete sentences; the “when” clause belongs to the second one. A semicolon marks that boundary.', 'hand-written'),
  ('boundaries', 'hard', 'Some early photographers relied on the wet-plate process, which required coating a glass plate with chemicals, exposing it, and developing it before it dried ______ as a result, those working outdoors had to bring a portable darkroom with them.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["dried, and,", "dried;", "dried,", "dried:"]'::jsonb, 'B', '“As a result” begins a new independent clause. A semicolon goes before it and a comma after it.', 'hand-written'),
  ('boundaries', 'hard', 'According to linguist Marina Ortiz, children who grow up hearing two languages do not simply learn each one more slowly ______ rather, they develop a distinct system in which the two languages interact from the very start.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["slowly", "slowly,", "slowly, and", "slowly;"]'::jsonb, 'D', '“Rather” is a transition beginning a new independent clause, so a semicolon is needed. A comma would create a splice.', 'hand-written'),
  ('boundaries', 'hard', 'Before announcing its decision, the committee reviewed proposals from three cities: Lyon, France ______ Porto, Portugal; and Ghent, Belgium.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["France,", "France;", "France", "France:"]'::jsonb, 'B', 'Because each item contains a comma, semicolons must separate them. The next item already uses one.', 'hand-written'),
  ('boundaries', 'hard', 'The chemist’s notebooks, long thought to have been destroyed in a laboratory fire ______ surfaced in 2009 at an estate sale in Ohio, where a graduate student recognized the handwriting.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["fire—", "fire;", "fire,", "fire"]'::jsonb, 'C', 'The interruption opened with a comma and must close with one. A dash would be a mismatched pair.', 'hand-written'),
  ('boundaries', 'hard', 'Few visitors to the ruined abbey notice the shallow grooves worn into its stone steps ______ yet these marks, left by centuries of monks walking the same path to prayer, may be the most intimate trace of daily life at the site.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["steps. Yet,", "steps", "steps,", "steps:"]'::jsonb, 'C', '“Yet” joins two complete sentences, so a comma goes before it. No punctuation makes a run-on, and a colon doesn’t fit before “yet.”', 'hand-written'),
  ('form_structure_sense', 'easy', 'The pack of wolves ______ across the frozen river each winter to reach its feeding grounds.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have traveled", "travel", "travels", "are traveling"]'::jsonb, 'C', 'The subject is “pack,” which is singular, so the verb is “travels.”', 'hand-written'),
  ('form_structure_sense', 'easy', 'Each of the runners ______ a number pinned to the front of a shirt during the race.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["wears", "wear", "have worn", "are wearing"]'::jsonb, 'A', '“Each” is singular, so it takes “wears.” “Of the runners” doesn’t change the subject.', 'hand-written'),
  ('form_structure_sense', 'easy', 'Last summer, Dana ______ to the coast with her family and collected shells on the beach.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["traveled", "travels", "will travel", "is traveling"]'::jsonb, 'A', '“Last summer” sets the past tense, which also matches “collected.”', 'hand-written'),
  ('form_structure_sense', 'easy', 'The students finished ______ projects a full week before the science fair.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["they’re", "their", "there", "its"]'::jsonb, 'B', 'The plural possessive “their” shows that the projects belong to the students.', 'hand-written'),
  ('form_structure_sense', 'easy', 'The ______ collars were all a bright shade of red, which made them easy to spot in the park.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["dogs", "dogs’", "dogs’s", "dog’s"]'::jsonb, 'B', '“All” the collars belong to more than one dog, so the plural possessive “dogs’” is needed.', 'hand-written'),
  ('form_structure_sense', 'easy', 'My aunt, along with her two sons, ______ at the farmers’ market every Saturday.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have worked", "works", "are working", "work"]'::jsonb, 'B', 'The subject is “aunt.” “Along with her two sons” doesn’t make it plural.', 'hand-written'),
  ('form_structure_sense', 'medium', 'The collection of essays, published shortly after the author’s death, ______ her experiences as a nurse during the war.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are describing", "describe", "have described", "describes"]'::jsonb, 'D', 'The subject is “collection,” not “essays,” so the verb is singular.', 'hand-written'),
  ('form_structure_sense', 'medium', 'Hoping to reduce noise in the city’s busiest neighborhoods, ______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["noise was reduced by sound barriers along the main highway.", "the main highway received new sound barriers from officials.", "officials installed sound barriers along the main highway.", "sound barriers were installed along the main highway by officials."]'::jsonb, 'C', 'The opening phrase describes who was hoping. That must come right after the comma, and only officials can hope.', 'hand-written'),
  ('form_structure_sense', 'medium', 'Since it was founded in 1892, the Sierra Club ______ to protect wilderness areas across the United States.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["worked", "works", "has worked", "will work"]'::jsonb, 'C', '“Since” plus a past date calls for the present perfect “has worked.”', 'hand-written'),
  ('form_structure_sense', 'medium', 'The ancient Greek city of Athens is famous for ______ democracy, in which male citizens voted directly on laws.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it’s", "its", "their", "they’re"]'::jsonb, 'B', '“Athens” is a singular city, and possession needs “its,” not the contraction “it’s.”', 'hand-written'),
  ('form_structure_sense', 'medium', 'Neither the mayor nor the council members ______ willing to comment on the proposed budget.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has been", "were", "is", "was"]'::jsonb, 'B', 'With “neither...nor,” the verb agrees with the nearer subject, “members,” which is plural.', 'hand-written'),
  ('form_structure_sense', 'medium', 'Among the most popular exhibits at the science center ______ a working model of a Mars rover and a room that simulates an earthquake.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are", "is", "has been", "was"]'::jsonb, 'A', 'The sentence is inverted: the subject is the compound “a working model... and a room,” so the verb is plural.', 'hand-written'),
  ('form_structure_sense', 'hard', 'The discovery of thousands of clay tablets at the site, many of them inscribed with records of grain shipments and tax payments, ______ historians a remarkably detailed view of daily administration in the ancient city.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has given", "give", "are giving", "have given"]'::jsonb, 'A', 'The subject is “discovery,” not “tablets” or “payments.” The long phrases between hide the singular subject.', 'hand-written'),
  ('form_structure_sense', 'hard', 'Having studied the migration routes of arctic terns for over a decade, ______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it was found by researcher Carsten Egevang that the birds travel far longer distances than earlier estimates had suggested.", "the distances traveled by the birds were found by researcher Carsten Egevang to be far longer than earlier estimates had suggested.", "earlier estimates of the birds’ travel were shown by researcher Carsten Egevang to be far too low.", "researcher Carsten Egevang found that the birds travel far longer distances than earlier estimates had suggested."]'::jsonb, 'D', 'The person who “studied” must follow the comma. Each wrong choice puts distances, estimates, or “it” in that position, which creates a dangling modifier.', 'hand-written'),
  ('form_structure_sense', 'hard', 'The architect’s drawings, together with a set of letters she exchanged with the city’s planners, ______ that the original design for the plaza included a much larger fountain.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["indicate", "indicates", "has indicated", "is indicating"]'::jsonb, 'A', 'The subject is “drawings,” plural. “Together with a set of letters” is an add-on, and “planners” is not the subject.', 'hand-written'),
  ('form_structure_sense', 'hard', 'By the time the expedition reached the coast in 1805, its members ______ more than two thousand miles on foot and by canoe.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are traveling", "travel", "will have traveled", "had traveled"]'::jsonb, 'D', '“By the time” plus a past event calls for the past perfect: the travel happened before reaching the coast.', 'hand-written'),
  ('form_structure_sense', 'hard', 'Scholars who have compared the two manuscripts agree that the poet Phillis Wheatley revised ______ early verses extensively, though they disagree about when those changes were made.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["their", "its", "her", "they’re"]'::jsonb, 'C', 'The verses belong to Phillis Wheatley, so the singular “her” is correct. “Their” would wrongly point to the scholars.', 'hand-written'),
  ('form_structure_sense', 'hard', 'The survival of these fragile paper maps, most of which were folded into trunks and forgotten for generations, ______ largely a matter of luck.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are", "have been", "were", "is"]'::jsonb, 'D', 'The subject is “survival,” which is singular. “Maps” and “generations” sit between the subject and the verb to mislead you.', 'hand-written'),
  ('transitions', 'easy', 'Penguins are birds, but they cannot fly. ______ they are excellent swimmers, using their wings like flippers to move through the water.', 'Which choice completes the text with the most logical transition?', '["For example,", "Similarly,", "However,", "Therefore,"]'::jsonb, 'C', 'The text contrasts what penguins can’t do with what they do well, so a contrast word fits.', 'hand-written'),
  ('transitions', 'easy', 'The school’s solar panels produce more electricity than the building uses. ______ the extra power is sold back to the local utility.', 'Which choice completes the text with the most logical transition?', '["Nevertheless,", "For instance,", "In contrast,", "As a result,"]'::jsonb, 'D', 'Producing extra electricity leads to selling it, a cause and effect.', 'hand-written'),
  ('transitions', 'easy', 'Many everyday foods come from plants in the grass family. ______ wheat, rice, and corn are all grasses.', 'Which choice completes the text with the most logical transition?', '["However,", "Finally,", "Instead,", "For example,"]'::jsonb, 'D', 'The second sentence gives specific examples of the first.', 'hand-written'),
  ('transitions', 'easy', 'To plant a tree, first dig a hole twice as wide as the root ball. ______ set the tree in the hole and fill it with soil.', 'Which choice completes the text with the most logical transition?', '["Next,", "For example,", "In contrast,", "Likewise,"]'::jsonb, 'A', 'The steps follow an order, so a sequence word fits.', 'hand-written'),
  ('transitions', 'easy', 'Reading aloud helps young children learn new words. ______ it gives parents and children a chance to spend time together.', 'Which choice completes the text with the most logical transition?', '["For instance,", "Instead,", "In addition,", "However,"]'::jsonb, 'C', 'The second sentence adds another benefit.', 'hand-written'),
  ('transitions', 'easy', 'The first attempt to climb the peak failed because of bad weather. ______ the team tried again the following year and reached the summit.', 'Which choice completes the text with the most logical transition?', '["For example,", "Therefore,", "Similarly,", "Still,"]'::jsonb, 'D', 'Despite the failure, they tried again, so a contrast word fits.', 'hand-written'),
  ('transitions', 'medium', 'Most stars in the night sky appear to stay in fixed positions relative to one another. The planets, ______ shift their positions from week to week, which is why ancient astronomers called them “wanderers.”', 'Which choice completes the text with the most logical transition?', '["for example,", "as a result,", "in addition,", "by contrast,"]'::jsonb, 'D', 'Planets moving is set against stars staying fixed, so a contrast is needed.', 'hand-written'),
  ('transitions', 'medium', 'Ice cream sales and sunburns both rise during the summer, but one doesn’t cause the other. Both are driven by a third factor: hot, sunny weather. ______ a correlation between two events doesn’t show that one produces the other.', 'Which choice completes the text with the most logical transition?', '["In other words,", "Nevertheless,", "Similarly,", "Meanwhile,"]'::jsonb, 'A', 'The last sentence restates the point of the example in general terms.', 'hand-written'),
  ('transitions', 'medium', 'Architect Julia Morgan designed more than seven hundred buildings during her career, including Hearst Castle. ______ she was the first woman admitted to the architecture program at the École des Beaux-Arts in Paris.', 'Which choice completes the text with the most logical transition?', '["Moreover,", "Nonetheless,", "Instead,", "Conversely,"]'::jsonb, 'A', 'The text adds another accomplishment, so an additive word fits.', 'hand-written'),
  ('transitions', 'medium', 'Early telephones required an operator to connect each call by hand. As the number of subscribers grew, this system became slow and costly. ______ engineers developed automatic switching equipment that could route calls without human help.', 'Which choice completes the text with the most logical transition?', '["Similarly,", "Consequently,", "Regardless,", "For instance,"]'::jsonb, 'B', 'The growing costs led to the new equipment, a cause and effect.', 'hand-written'),
  ('transitions', 'medium', 'Some scientists describe the human gut as an ecosystem. ______ an ecosystem such as a forest, it contains many interacting species, and removing one can affect the others.', 'Which choice completes the text with the most logical transition?', '["Like", "Unlike", "Despite", "Instead of"]'::jsonb, 'A', 'The sentence names a similarity between the gut and a forest.', 'hand-written'),
  ('transitions', 'medium', 'Critics expected the small film to disappear from theaters within a week. ______ it ran for six months and earned twenty times its budget.', 'Which choice completes the text with the most logical transition?', '["Instead,", "Specifically,", "Additionally,", "Likewise,"]'::jsonb, 'A', 'What happened replaced what was expected, so “Instead” fits.', 'hand-written'),
  ('transitions', 'hard', 'Economists often assume that people respond to incentives in predictable ways. Paying blood donors, it would seem, should increase donations. ______ in some studies, offering small payments actually reduced donations, apparently because payment turned an act of generosity into a mere transaction.', 'Which choice completes the text with the most logical transition?', '["Surprisingly,", "Likewise,", "In short,", "Accordingly,"]'::jsonb, 'A', 'The result runs against the expected outcome. “Accordingly” and “Likewise” imply the result fits the expectation.', 'hand-written'),
  ('transitions', 'hard', 'The sculptor Barbara Hepworth rejected the idea that her abstract forms were removed from nature. Her pierced stone shapes, she insisted, grew from the hills and coast of Cornwall. ______ although her work contains no literal landscapes, she considered it deeply rooted in place.', 'Which choice completes the text with the most logical transition?', '["Meanwhile,", "Nevertheless,", "Alternatively,", "Thus,"]'::jsonb, 'D', 'The final sentence draws a conclusion from her statements. “Nevertheless” would wrongly signal a contradiction; the “although” already handles the contrast within the sentence.', 'hand-written'),
  ('transitions', 'hard', 'Glass appears to be a solid, and in everyday life it behaves like one. At the atomic level, ______ its structure lacks the orderly repeating pattern of a crystal, resembling instead a liquid frozen in place.', 'Which choice completes the text with the most logical transition?', '["likewise,", "therefore,", "however,", "for example,"]'::jsonb, 'C', 'The atomic structure differs from the everyday appearance, so a contrast is needed.', 'hand-written'),
  ('transitions', 'hard', 'In 1854, physician John Snow mapped cholera deaths in London and traced them to a single water pump. Most of his colleagues believed the disease spread through foul air. Snow’s map, ______ did more than stop one outbreak: it challenged the prevailing theory of how disease travels.', 'Which choice completes the text with the most logical transition?', '["on the other hand,", "meanwhile,", "by comparison,", "then,"]'::jsonb, 'D', '“Then” here means “therefore”: it sums up the significance of the facts given. The others would signal a simultaneous event or a contrast that isn’t there.', 'hand-written'),
  ('transitions', 'hard', 'Some historians argue that the invention of the mechanical clock transformed medieval labor by making time something that could be measured and sold. ______ others caution that for centuries most rural workers continued to organize their days by the sun and the seasons, so the change was slower than this account implies.', 'Which choice completes the text with the most logical transition?', '["Yet", "Hence", "Indeed", "Similarly"]'::jsonb, 'A', 'The second group of historians qualifies the first group’s claim, so a contrast is needed. “Indeed” would support it.', 'hand-written'),
  ('transitions', 'hard', 'Astronomers had predicted that the comet would break apart on its close pass by the Sun. Observers watched as its bright tail faded and vanished behind the solar disk. ______ hours later, a smaller but intact comet emerged on the other side, to the astonishment of researchers.', 'Which choice completes the text with the most logical transition?', '["Likewise,", "Therefore,", "Then,", "In other words,"]'::jsonb, 'C', 'The events follow in time, and the emergence wasn’t caused by the fading. “Therefore” would wrongly claim a logical result.', 'hand-written'),
  ('rhetorical_synthesis', 'easy', 'While researching a topic, a student has taken the following notes:
• The Golden Gate Bridge connects San Francisco and Marin County.
• Construction began in 1933.
• The bridge opened in 1937.
• It is painted a color called International Orange.', 'The student wants to state when the bridge opened. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Golden Gate Bridge opened in 1937.", "Construction on the Golden Gate Bridge began in 1933.", "The Golden Gate Bridge is painted International Orange.", "The Golden Gate Bridge connects San Francisco and Marin County."]'::jsonb, 'A', 'Only this choice gives the opening date.', 'hand-written'),
  ('rhetorical_synthesis', 'easy', 'While researching a topic, a student has taken the following notes:
• Sunflowers can grow more than ten feet tall.
• Young sunflowers turn to face the sun as it moves across the sky.
• Their seeds are used to make oil.', 'The student wants to explain why the plant is called a sunflower. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Sunflowers get their name because young plants turn to face the sun.", "Sunflower seeds are used to make oil.", "Sunflowers are tall plants with useful seeds.", "Sunflowers can grow more than ten feet tall."]'::jsonb, 'A', 'The goal is the reason for the name, which is the turning behavior.', 'hand-written'),
  ('rhetorical_synthesis', 'easy', 'While researching a topic, a student has taken the following notes:
• African elephants can weigh up to 14,000 pounds.
• Asian elephants can weigh up to 11,000 pounds.
• African elephants have larger ears.
• Both species live in herds.', 'The student wants to compare the sizes of the two animals. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Asian elephants can weigh up to 11,000 pounds.", "Both African and Asian elephants live in herds.", "African elephants can weigh up to 14,000 pounds, while Asian elephants reach about 11,000 pounds.", "African elephants have larger ears and live in herds."]'::jsonb, 'C', 'Only this choice gives both animals’ sizes.', 'hand-written'),
  ('rhetorical_synthesis', 'easy', 'While researching a topic, a student has taken the following notes:
• Octavia Butler was an American science fiction writer.
• She published Kindred in 1979.
• She won two Hugo Awards.', 'The student wants to introduce the author to readers unfamiliar with her. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Octavia Butler, an American science fiction writer, won two Hugo Awards.", "Butler’s 1979 book is Kindred.", "Kindred was published in 1979.", "Two Hugo Awards were won."]'::jsonb, 'A', 'An introduction should say who she is. Only this choice identifies her.', 'hand-written'),
  ('rhetorical_synthesis', 'easy', 'While researching a topic, a student has taken the following notes:
• The Appalachian Trail runs through fourteen states.
• It is about 2,190 miles long.
• It was completed in 1937.', 'The student wants to emphasize how long the trail is. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["At about 2,190 miles, the Appalachian Trail stretches through fourteen states.", "The Appalachian Trail was completed in 1937.", "The Appalachian Trail is an American trail that was completed long ago.", "Hikers can visit the Appalachian Trail."]'::jsonb, 'A', 'This choice uses the mileage and number of states to show its length.', 'hand-written'),
  ('rhetorical_synthesis', 'easy', 'While researching a topic, a student has taken the following notes:
• Stephanie Kwolek was a chemist at DuPont.
• In 1965, she invented Kevlar.
• Kevlar is a strong, lightweight fiber.
• It is mainly used in protective vests.', 'The student wants to present the main use of the invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Stephanie Kwolek was a chemist at DuPont.", "Kevlar, invented by Stephanie Kwolek, is mainly used in protective vests.", "Kevlar was invented in 1965.", "Kevlar is a fiber that is strong and lightweight."]'::jsonb, 'B', 'Only this choice states the use.', 'hand-written'),
  ('rhetorical_synthesis', 'medium', 'While researching a topic, a student has taken the following notes:
• Two 2019 studies examined how urban noise affects birds.
• One study, in Madrid, tracked great tits for three years.
• The other, in Toronto, tracked song sparrows for one breeding season.
• Both found that birds near loud roads sang at higher pitches.', 'The student wants to emphasize a difference between the two studies. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Both 2019 studies found that birds near loud roads sang at higher pitches.", "Two 2019 studies, one in Madrid and one in Toronto, examined how urban noise affects birds.", "While the Madrid study tracked great tits for three years, the Toronto study followed song sparrows for just one breeding season.", "Great tits and song sparrows both sang at higher pitches near loud roads."]'::jsonb, 'C', 'The goal is a difference, which is the species and duration. The others state what the studies share.', 'hand-written'),
  ('rhetorical_synthesis', 'medium', 'While researching a topic, a student has taken the following notes:
• The Rosetta Stone was found in Egypt in 1799.
• It bears the same text in three scripts: hieroglyphic, Demotic, and Ancient Greek.
• Scholars could already read Ancient Greek.
• Using the Greek, Jean-François Champollion deciphered hieroglyphs in 1822.', 'The student wants to explain the significance of the discovery. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Hieroglyphic, Demotic, and Ancient Greek are the three scripts on the Rosetta Stone.", "Because the Rosetta Stone repeated one text in three scripts, including readable Greek, it enabled scholars to decipher hieroglyphs.", "Jean-François Champollion deciphered hieroglyphs in 1822, and the stone was found in 1799.", "The Rosetta Stone, found in Egypt in 1799, bears text in three scripts."]'::jsonb, 'B', 'Significance means why it mattered: it unlocked hieroglyphs. The others only report facts.', 'hand-written'),
  ('rhetorical_synthesis', 'medium', 'While researching a topic, a student has taken the following notes:
• Tardigrades are microscopic animals found in moss and water.
• In 2007, researchers exposed tardigrades to the vacuum of space.
• Many of them survived and later reproduced.', 'The student wants to present the study’s finding to an audience unfamiliar with tardigrades. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Tardigrades, microscopic animals found in moss and water, survived exposure to the vacuum of space in a 2007 study.", "Many tardigrades survived and later reproduced.", "In 2007, researchers conducted a study in space.", "Tardigrades can be found in moss and in water."]'::jsonb, 'A', 'The audience needs to know what tardigrades are plus the finding. Only this choice has both.', 'hand-written'),
  ('rhetorical_synthesis', 'medium', 'While researching a topic, a student has taken the following notes:
• Edmonia Lewis was a sculptor born in 1844.
• She was of African American and Ojibwe descent.
• She faced racial discrimination in the United States.
• She moved to Rome and won international fame.', 'The student wants to emphasize the artist’s achievement in spite of obstacles. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Edmonia Lewis, who was born in 1844, was of African American and Ojibwe descent.", "Edmonia Lewis was a sculptor who moved from the United States to Rome.", "Rome was the city where the sculptor Edmonia Lewis lived.", "Despite facing racial discrimination in the United States, Edmonia Lewis won international fame as a sculptor."]'::jsonb, 'D', '“Despite” links the obstacle to her achievement. The others omit one or both.', 'hand-written'),
  ('rhetorical_synthesis', 'medium', 'While researching a topic, a student has taken the following notes:
• Crop rotation is the practice of changing what is grown in a field each year.
• Beans add nitrogen to soil.
• Corn uses large amounts of nitrogen.
• Farmers have used crop rotation for centuries.', 'The student wants to explain how the technique works. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Farmers have used crop rotation for centuries.", "In crop rotation, a farmer might follow beans, which add nitrogen to soil, with corn, which uses a lot of it.", "Beans and corn are two crops that farmers have grown for centuries.", "Corn uses large amounts of nitrogen from the soil."]'::jsonb, 'B', 'Explaining how it works requires connecting the two crops’ effects on nitrogen.', 'hand-written'),
  ('rhetorical_synthesis', 'medium', 'While researching a topic, a student has taken the following notes:
• The Svalbard Global Seed Vault opened in Norway in 2008.
• It stores duplicates of seeds from gene banks around the world.
• It is built into a mountain above the Arctic Circle.
• Its aim is to safeguard crop diversity against disasters.', 'The student wants to describe the purpose of the program. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Built into a mountain, the Svalbard Global Seed Vault lies above the Arctic Circle.", "The Svalbard Global Seed Vault, opened in 2008, is located in Norway.", "Gene banks around the world contribute seeds to a vault in a mountain.", "The Svalbard Global Seed Vault stores duplicate seeds to safeguard crop diversity against disasters."]'::jsonb, 'D', 'Only this choice states what the vault is for.', 'hand-written'),
  ('rhetorical_synthesis', 'hard', 'While researching a topic, a student has taken the following notes:
• Historian Lena Brandt studied shipping records from a medieval port.
• She concluded that the port’s decline began around 1340.
• Archaeologist Tomás Rey excavated warehouses at the same port.
• Pottery layers led him to date the decline to the mid-1300s.', 'The student wants to emphasize that the two scholars reached a similar conclusion by different methods. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Brandt, a historian, and Rey, an archaeologist, both studied a medieval port that declined.", "Although Brandt dated the decline to around 1340, Rey found evidence for a different period.", "Working from shipping records and from excavated pottery, respectively, Brandt and Rey each dated the port’s decline to the mid-fourteenth century.", "Rey excavated warehouses and pottery layers, while Brandt read shipping records from the port."]'::jsonb, 'C', 'Only this choice names both methods and the shared result. The last wrong choice invents a disagreement.', 'hand-written'),
  ('rhetorical_synthesis', 'hard', 'While researching a topic, a student has taken the following notes:
• A 2021 study tested a reading program in twelve rural schools.
• Students in the program improved their reading scores by 15 percent.
• Scores of similar students outside the program rose 6 percent.
• The study didn’t include any urban schools.', 'The student wants to acknowledge a limitation of the study while presenting its main result. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Students in the reading program outpaced their peers, gaining 15 percent versus 6 percent, though the study included only rural schools.", "A 2021 study tested a reading program in twelve rural schools and did not include urban schools.", "Because the study did not include urban schools, the 15 percent improvement among rural students cannot be measured.", "Students in the reading program improved their scores by 15 percent, more than the 6 percent improvement of similar students."]'::jsonb, 'A', 'This choice gives both the result and the limitation. The last choice falsely says the improvement can’t be measured.', 'hand-written'),
  ('rhetorical_synthesis', 'hard', 'While researching a topic, a student has taken the following notes:
• For much of the twentieth century, geologists held that continents were fixed in place.
• In 1912, Alfred Wegener proposed that continents slowly drift.
• He cited matching fossils on separate continents.
• His idea gained acceptance after seafloor spreading was discovered in the 1960s.', 'The student wants to present the theory as a challenge to an earlier view. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Wegener’s 1912 proposal that continents drift, supported by matching fossils, contradicted the view that continents were fixed in place.", "Geologists in the twentieth century studied continents, fossils, and the seafloor.", "Alfred Wegener cited matching fossils on separate continents when he proposed his idea in 1912.", "Seafloor spreading, discovered in the 1960s, led to the acceptance of Wegener’s idea."]'::jsonb, 'A', 'Only this choice sets his theory against the earlier view.', 'hand-written'),
  ('rhetorical_synthesis', 'hard', 'While researching a topic, a student has taken the following notes:
• In 2005, artists in Philadelphia began painting murals on buildings in a run-down district.
• More than 200 murals were completed by 2015.
• Surveys found that the share of visitors describing the district as “welcoming” rose from 22 percent to 61 percent.
• Property taxes in the district stayed about the same.', 'The student wants to use the example to support the claim that public art can change how a neighborhood is perceived. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Artists in Philadelphia began painting murals in a run-down district in 2005.", "Between 2005 and 2015, artists completed more than 200 murals in a Philadelphia district.", "After more than 200 murals appeared in a Philadelphia district, the share of visitors calling it “welcoming” rose from 22 percent to 61 percent.", "Property taxes in a Philadelphia district stayed about the same after artists painted murals there."]'::jsonb, 'C', 'Perception is measured by the survey, so this choice links the murals to the change. The others report activity or taxes.', 'hand-written'),
  ('rhetorical_synthesis', 'hard', 'While researching a topic, a student has taken the following notes:
• Most fish species leave their eggs unattended.
• Seahorses live in shallow coastal waters.
• In seahorses, the female deposits eggs in a pouch on the male.
• The male carries the eggs until they hatch.', 'The student wants to highlight what is unusual about the species’ reproduction compared with that of most fish. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Seahorses, which live in shallow coastal waters, are a kind of fish that reproduces.", "The female seahorse deposits her eggs in a pouch on the male.", "Whereas most fish leave their eggs unattended, male seahorses carry eggs in a pouch until they hatch.", "Most fish species leave their eggs unattended, and many live in the ocean."]'::jsonb, 'C', 'The goal requires a comparison with most fish and the unusual trait. The second choice gives only the trait, without the comparison.', 'hand-written'),
  ('rhetorical_synthesis', 'hard', 'While researching a topic, a student has taken the following notes:
• A city offered rebates to households that bought efficient appliances.
• Planners expected electricity use to fall by 10 percent.
• Electricity use fell by only 2 percent.
• Follow-up surveys found that many households kept their old appliances running as well, in garages and basements.', 'The student wants to explain why the policy’s results surprised its designers. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Follow-up surveys found that many households kept old appliances in garages and basements.", "Planners expected electricity use to fall by 10 percent after offering rebates for efficient appliances.", "A city’s rebates led households to buy efficient appliances, and electricity use fell by 2 percent.", "Planners expected a 10 percent drop in electricity use, but because many households kept running their old appliances alongside the new ones, use fell only 2 percent."]'::jsonb, 'D', 'Only this choice contrasts the expectation with the result and gives the reason.', 'hand-written');
